package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import java.util.*;
import org.json.*;
import org.junit.*;

public final class ProjectFileTreeTest {
    private JSONArray files;
    @Before public void create(){files=new JSONArray();}
    private void file(String path,String change,boolean binary)throws Exception{files.put(new JSONObject().put("path",path).put("change",change).put("sha256",change.equals("deleted")?"absent":"a".repeat(64)).put("bytes",change.equals("deleted")?0:20).put("binary",binary));}
    @Test public void directoriesPrecedeFilesAndFullNativePathsRemainStable()throws Exception{file("package.json","unchanged",false);file("src/app/main.js","modified",false);file("src/app/style.css","unchanged",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of());assertEquals(3,tree.recordCount);assertEquals("src/app",tree.roots.get(0).path);assertEquals("src/app",tree.roots.get(0).label);assertEquals("package.json",tree.roots.get(1).path);List<ProjectFileTree.Row> rows=tree.visible(Set.of("src/app"),"",ProjectFileTree.ALL);assertEquals(4,rows.size());assertEquals("src/app/main.js",rows.get(1).node.path);assertEquals(1,rows.get(1).depth);assertTrue(rows.get(0).expanded);}
    @Test public void compactSingleChildDirectoryChainsHaveAtMostTwoNodesPerFile()throws Exception{for(int i=0;i<500;i++)file("root-"+i+"/"+"d/".repeat(50)+"file.txt","unchanged",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of());assertEquals(1000,tree.nodeCount);assertEquals(500,tree.roots.size());assertTrue(tree.roots.get(0).label.length()>80);}
    @Test public void changedAndDraftFiltersAreDifferentFromSavedFileFacts()throws Exception{file("src/a.js","unchanged",false);file("src/b.js","modified",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of("src/a.js"));List<ProjectFileTree.Row> changed=tree.visible(Set.of("src"),"",ProjectFileTree.CHANGED);assertEquals(3,changed.size());List<ProjectFileTree.Row> draft=tree.visible(Set.of("src"),"",ProjectFileTree.DRAFTS);assertEquals(2,draft.size());assertEquals("unchanged",draft.get(1).node.change);assertTrue(draft.get(1).node.draft);}
    @Test public void unsavedNewDraftIsExplicitlyNotAnExistingFileOrVersion()throws Exception{file("src/a.js","unchanged",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of("new/idea.js"));List<ProjectFileTree.Row> rows=tree.visible(tree.ancestors("new/idea.js"),"idea",ProjectFileTree.DRAFTS);assertEquals(1,rows.size());assertTrue(rows.get(0).node.draftOnly);assertEquals(-1,rows.get(0).node.bytes);assertEquals("",rows.get(0).node.sha256);assertEquals("new/idea.js",rows.get(0).displayName);}
    @Test public void unsavedConflictingPathDoesNotHideActualDirectoryOrOverwriteIt()throws Exception{file("src/a.js","unchanged",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of("src"));assertEquals(2,tree.roots.size());assertTrue(tree.roots.get(0).directory);assertFalse(tree.roots.get(1).directory);assertTrue(tree.roots.get(1).draftOnly);}
    @Test public void deletedAndBinaryFactsRemainVisibleWithoutPretendingEditableText()throws Exception{file("assets/image.png","modified",true);file("old.js","deleted",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of());List<ProjectFileTree.Row> rows=tree.visible(Set.of("assets"),"",ProjectFileTree.ALL);assertTrue(rows.get(1).node.binary);assertTrue(rows.get(2).node.deleted);assertEquals("absent",rows.get(2).node.sha256);}
    @Test public void searchReturnsActualFullPathsRatherThanExpandingEveryDirectory()throws Exception{file("src/one/main.js","modified",false);file("src/two/other.js","unchanged",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of());List<ProjectFileTree.Row> rows=tree.visible(Set.of(),"ONE/MAIN",ProjectFileTree.ALL);assertEquals(1,rows.size());assertFalse(rows.get(0).node.directory);assertEquals("src/one/main.js",rows.get(0).displayName);assertEquals(0,rows.get(0).depth);}
    @Test public void retainedChildExpansionSurvivesDirectoryCompactionChanging()throws Exception{file("src/a/one.js","unchanged",false);file("src/b/two.js","unchanged",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of());List<ProjectFileTree.Row> rows=tree.visible(Set.of("src/a"),"",ProjectFileTree.ALL);assertTrue(rows.get(0).expanded);assertEquals(Set.of("src","src/a"),tree.ancestors("src/a/one.js"));assertTrue(rows.stream().anyMatch(row->row.node.path.equals("src/a/one.js")));assertFalse(rows.stream().anyMatch(row->row.node.path.equals("src/b/two.js")));}
    @Test public void duplicateUnsafeAndConflictingActualPathsFailClosed()throws Exception{file("a.js","unchanged",false);file("a.js","modified",false);assertThrows(IllegalArgumentException.class,()->ProjectFileTree.from(files,List.of()));files=new JSONArray();file("a","unchanged",false);file("a/b","unchanged",false);assertThrows(IllegalArgumentException.class,()->ProjectFileTree.from(files,List.of()));assertThrows(IllegalArgumentException.class,()->ProjectFileTree.from(new JSONArray(),List.of("../not-source")));}
    @Test public void formerDirectoryReplacedByFileKeepsDeletedRowsSeparateFromCurrentFiles()throws Exception{file("a","added",false);file("a/old.js","deleted",false);file("b","deleted",false);file("b/new.js","added",false);ProjectFileTree tree=ProjectFileTree.from(files,List.of());List<ProjectFileTree.Row> rows=tree.visible(Set.of("a","b"),"",ProjectFileTree.ALL);assertEquals(6,rows.size());assertEquals(4,tree.recordCount);assertEquals(2,rows.stream().filter(row->row.node.deleted).count());assertEquals(2,rows.stream().filter(row->!row.node.directory&&!row.node.deleted).count());}
}
